[
  {
    "name": "강원도 평창 오대산",
    "reason": "가을 초입의 선선한 날씨에 혼자 조용히 걷기 좋은 힐링 여행지다. 숲길과 계곡 풍경이 편안하고, 2일 일정으로 무리 없이 자연 속 휴식을 즐기기 좋다. 비교적 큰 비용 없이도 만족도가 높다.",
    "tip": "대중교통 이용 시 진부역이나 강릉 방면 연계를 미리 확인하면 좋다. 걷기 편한 운동화와 가벼운 바람막이를 준비하면 편하다.",
    "area_hint": "강원도 평창군",
    "category": "자연"
  },
  {
    "name": "전북 전주 한옥마을",
    "reason": "혼자서도 부담 없이 천천히 걷고 쉬기 좋은 여행지다. 한옥 골목의 고즈넉한 분위기와 전주천 산책이 잘 어울려 힐링 여행에 적합하다. 예산 10만원 안에서도 숙박과 식사를 비교적 알차게 구성할 수 있다.",
    "tip": "한옥마을 중심지만 보기보다 아침이나 저녁 시간대에 골목과 전주천 쪽을 함께 걸으면 더 한적하게 즐길 수 있다.",
    "area_hint": "전라북도 전주시",
    "category": "역사"
  },
  {
    "name": "충북 제천 청풍호",
    "reason": "호수 풍경이 차분하고 가을의 맑은 공기를 느끼며 쉬기 좋은 곳이다. 혼자 멍하니 풍경을 보거나 가볍게 산책하기 좋고, 1박 2일 일정으로 여유 있게 다녀오기 적당하다. 비교적 조용한 분위기라 힐링 목적에 잘 맞는다.",
    "tip": "청풍호 주변은 일교차가 있을 수 있어 얇은 겉옷을 챙기면 좋다. 이동 동선을 줄이려면 청풍문화재단지나 전망 좋은 카페를 함께 묶어 방문하는 것이 효율적이다.",
    "area_hint": "충청북도 제천시",
    "category": "자연"
  }
]
